import logo from '../logo.svg';
import '../Assets/Home.css';
import Calendar from './Calendar';
import EventForm from './EventForm';

export default function () {
  return (
    <div className="container">
      <div className="left-div">
        <EventForm />
      </div>
      <div className="right-div">
        <Calendar />
      </div>
    </div>
  );
}
